using System.Reflection;
using System.Text.Json;

namespace CIS.TypeManagement;

// Owned validated selections. No type loading, directory scanning or fallback discovery occurs here.
internal sealed class AssemblyInventory
{
    private AssemblyInventory(string manifestPath, IReadOnlyList<SelectedAssembly> assemblies)
    {
        ManifestPath = manifestPath;
        Assemblies = assemblies;
    }

    internal string ManifestPath { get; }
    internal IReadOnlyList<SelectedAssembly> Assemblies { get; }

    internal static async Task<AssemblyInventory> ReadAsync(string manifestPath, Assembly hostAssembly,
        CancellationToken cancellationToken)
    {
        byte[] bytes;
        try
        {
            bytes = await File.ReadAllBytesAsync(manifestPath, cancellationToken).ConfigureAwait(false);
        }
        catch (Exception error) when (error is IOException or UnauthorizedAccessException)
        {
            throw Invalid(manifestPath, "The required assembly inventory could not be read.", error);
        }

        try
        {
            ReadOnlyMemory<byte> json = bytes;
            if (bytes.AsSpan().StartsWith(new byte[] { 0xef, 0xbb, 0xbf })) { json = json[3..]; }
            using var document = JsonDocument.Parse(json);
            ValidateUniqueProperties(document.RootElement, cancellationToken);
            var root = document.RootElement;
            RequireKind(root, JsonValueKind.Object, "inventory");
            if (!root.TryGetProperty("schemaVersion", out var version))
            {
                throw new FormatException("Required inventory schemaVersion is missing.");
            }
            if (version.ValueKind != JsonValueKind.Number || !version.TryGetInt32(out var number))
            {
                throw new FormatException($"Expected integer inventory schemaVersion 1; observed {version.ValueKind}.");
            }
            if (number != 1)
            {
                throw new FormatException($"Unsupported inventory schemaVersion {number}; expected 1.");
            }
            string hostIdentity = ReadString(root, "hostAssembly");
            if (!string.Equals(hostIdentity, hostAssembly.FullName, StringComparison.Ordinal))
            {
                throw new TypeManagerInitializationException(TypeManagerFailureKind.InvalidInventory,
                    "The inventory hostAssembly does not match the supplied host assembly.",
                    new FormatException("Host identity mismatch."), manifestPath: manifestPath,
                    assemblyIdentity: hostIdentity, actualAssemblyIdentity: hostAssembly.FullName);
            }
            if (!root.TryGetProperty("assemblies", out var entries))
            {
                throw new FormatException("Required assemblies list is missing.");
            }
            RequireKind(entries, JsonValueKind.Array, "assemblies");
            if (entries.GetArrayLength() == 0)
            {
                throw new FormatException("The assemblies list must not be empty.");
            }

            string directory = Path.GetDirectoryName(manifestPath)!;
            var byName = new Dictionary<string, SelectedAssembly>(StringComparer.OrdinalIgnoreCase);
            var byPath = new Dictionary<string, SelectedAssembly>(OperatingSystem.IsWindows()
                ? StringComparer.OrdinalIgnoreCase : StringComparer.Ordinal);
            bool containsHost = false;
            foreach (var entry in entries.EnumerateArray())
            {
                cancellationToken.ThrowIfCancellationRequested();
                string? identity = null;
                string? assetPath = null;
                try
                {
                    RequireKind(entry, JsonValueKind.Object, "assembly entry");
                    identity = ReadString(entry, "assemblyName");
                    string relativePath = ReadString(entry, "relativePath");
                    assetPath = relativePath;
                    AssemblyName name;
                    try
                    {
                        name = new AssemblyName(identity);
                    }
                    catch (Exception error) when (error is ArgumentException or FileLoadException)
                    {
                        throw Invalid(manifestPath, "Invalid selected assembly identity.", error, assetPath: assetPath, assemblyIdentity: identity);
                    }
                    if (string.IsNullOrWhiteSpace(name.Name) || name.Version is null ||
                        name.CultureName is null || name.GetPublicKeyToken() is null ||
                        !string.Equals(name.FullName, identity, StringComparison.Ordinal))
                    {
                        throw new FormatException($"Expected a complete canonical assembly identity: {identity}");
                    }
                    string path = ResolvePath(directory, relativePath);
                    assetPath = path;
                    if (!File.Exists(path))
                    {
                        throw Invalid(manifestPath, "A required selected assembly file is missing or inaccessible.",
                            new FileNotFoundException("Required selected assembly was not found.", path), path, identity);
                    }
                    var selected = new SelectedAssembly(identity, name.Name, path);
                    if (byName.TryGetValue(name.Name, out var previous))
                    {
                        if (string.Equals(previous.Identity, identity, StringComparison.Ordinal) && byPath.Comparer.Equals(previous.Path, path))
                        {
                            continue;
                        }
                        throw Invalid(manifestPath, "Conflicting selections have the same simple assembly name.",
                            new FormatException($"Conflicting selections: {previous.Identity} and {identity}."), path, identity);
                    }
                    if (byPath.TryGetValue(path, out previous) && previous != selected)
                    {
                        throw Invalid(manifestPath, "Conflicting identities select the same assembly file.",
                            new FormatException($"Conflicting selections: {previous.Identity} and {identity}."), path, identity);
                    }
                    byName[name.Name] = selected;
                    byPath[path] = selected;
                    containsHost |= string.Equals(identity, hostIdentity, StringComparison.Ordinal);
                }
                catch (Exception error) when (error is FormatException or ArgumentException or InvalidOperationException)
                {
                    throw Invalid(manifestPath, "The selected inventory entry is invalid: " + error.Message,
                        error, assetPath, identity);
                }
            }
            if (!containsHost)
            {
                throw new FormatException("The assemblies list must contain the host assembly.");
            }
            var selectedAssemblies = byName.Values.OrderBy(item => item.Identity, StringComparer.Ordinal).ToArray();
            return new AssemblyInventory(manifestPath, Array.AsReadOnly(selectedAssemblies));
        }
        catch (Exception error) when (error is JsonException or FormatException or ArgumentException or InvalidOperationException)
        {
            throw Invalid(manifestPath, "The assembly inventory is invalid: " + error.Message, error);
        }
    }

    private static string ResolvePath(string directory, string relativePath)
    {
        if (Path.IsPathRooted(relativePath) || relativePath.Contains(':') || relativePath.Contains('\\') ||
            relativePath.Split('/').Any(segment => segment.Length == 0 || segment is "." or ".." ||
                (OperatingSystem.IsWindows() && (segment.EndsWith('.') || segment.EndsWith(' ')))))
        {
            throw new FormatException($"Expected a normalized relative assembly path: {relativePath}");
        }
        string path = Path.GetFullPath(relativePath, directory);
        string check = Path.GetRelativePath(directory, path);
        if (Path.IsPathRooted(check) || check == ".." || check.StartsWith(".." + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new FormatException($"Selected assembly path escapes the inventory directory: {relativePath}");
        }
        return path;
    }

    private static string ReadString(JsonElement parent, string property)
    {
        if (!parent.TryGetProperty(property, out var value) || value.ValueKind != JsonValueKind.String ||
            string.IsNullOrWhiteSpace(value.GetString()))
        {
            throw new FormatException($"Expected a nonblank string for {property}.");
        }
        return value.GetString()!;
    }

    private static void RequireKind(JsonElement value, JsonValueKind kind, string description)
    {
        if (value.ValueKind != kind)
        {
            throw new FormatException($"Expected {description} to be {kind}.");
        }
    }

    private static void ValidateUniqueProperties(JsonElement value, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (value.ValueKind == JsonValueKind.Object)
        {
            var names = new HashSet<string>(StringComparer.Ordinal);
            foreach (var property in value.EnumerateObject())
            {
                if (!names.Add(property.Name))
                {
                    throw new FormatException($"Duplicate JSON property: {property.Name}");
                }
                ValidateUniqueProperties(property.Value, cancellationToken);
            }
        }
        else if (value.ValueKind == JsonValueKind.Array)
        {
            foreach (var element in value.EnumerateArray())
            {
                ValidateUniqueProperties(element, cancellationToken);
            }
        }
        else if (value.ValueKind == JsonValueKind.String)
        {
            // JsonDocument defers string decoding; unknown fields must still contain valid UTF-8/Unicode.
            _ = value.GetString();
        }
    }

    private static TypeManagerInitializationException Invalid(string manifestPath, string message, Exception inner,
        string? assetPath = null, string? assemblyIdentity = null)
    {
        return new TypeManagerInitializationException(TypeManagerFailureKind.InvalidInventory, message, inner,
            manifestPath: manifestPath, assetPath: assetPath, assemblyIdentity: assemblyIdentity);
    }
}

internal sealed record SelectedAssembly(string Identity, string SimpleName, string Path);

using System.Diagnostics.CodeAnalysis;
using System.Reflection;

namespace CIS.TypeManagement;

/// <summary>A complete, fixed runtime type catalog prepared for one host.</summary>
public interface ITypeManager
{
    /// <summary>Gets selected actual assemblies in ordinal full-identity order.</summary>
    IReadOnlyList<Assembly> Assemblies { get; }
    /// <summary>Gets all defined types, including nonpublic and open generic definitions, in deterministic order.</summary>
    IReadOnlyList<Type> Types { get; }
    /// <summary>Gets immutable diagnostics captured during preparation.</summary>
    TypeManagerPreparationReport PreparationReport { get; }
    /// <summary>Gets cached definitions for an actual assembly in this catalog.</summary>
    /// <exception cref="ArgumentNullException">The assembly is null.</exception>
    /// <exception cref="ArgumentException">The assembly is not in this catalog.</exception>
    IReadOnlyList<Type> GetDefinedTypes(Assembly assembly);
    /// <summary>Gets closed concrete classes assignable to a closed runtime class or interface contract.</summary>
    /// <remarks>Results include nonpublic classes without usable constructors. Queries never create instances or extend catalog membership.</remarks>
    /// <exception cref="ArgumentNullException">The contract is null.</exception>
    /// <exception cref="ArgumentException">The contract is not a supported default-context runtime class or interface.</exception>
    IReadOnlyList<Type> GetImplementations(Type contractType);
    /// <summary>Looks up an exact, ordinal assembly-qualified name without normalization or runtime loading.</summary>
    /// <exception cref="ArgumentNullException">The name is null.</exception>
    /// <exception cref="ArgumentException">The name is empty or whitespace.</exception>
    bool TryGetType(string assemblyQualifiedTypeName, [NotNullWhen(true)] out Type? type);
}

/// <summary>Convenience queries that preserve the non-generic matching contract.</summary>
public static class TypeManagerExtensions
{
    /// <summary>Queries the manager using the actual runtime type of <typeparamref name="TContract"/>.</summary>
    /// <exception cref="ArgumentNullException">The manager is null.</exception>
    public static IReadOnlyList<Type> GetImplementations<TContract>(this ITypeManager manager)
    {
        ArgumentNullException.ThrowIfNull(manager);
        return manager.GetImplementations(typeof(TContract));
    }
}

using System.Reflection;
using System.Runtime.Loader;

namespace CIS.TypeManagement;

internal sealed record PreparationInputs(Assembly HostAssembly, string ManifestPath, Type[] Contracts)
{
    internal static PreparationInputs Capture(TypeManagerOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);
        ArgumentNullException.ThrowIfNull(options.HostAssembly, nameof(options));
        ArgumentNullException.ThrowIfNull(options.PrecomputedContracts, nameof(options));

        var host = options.HostAssembly;
        if (host.GetType() != typeof(object).Assembly.GetType() || host.IsDynamic ||
            AssemblyLoadContext.GetLoadContext(host) != AssemblyLoadContext.Default)
        {
            throw new ArgumentException("HostAssembly must be an ordinary default-context runtime assembly.", nameof(options));
        }

        string? suppliedPath = options.AssemblyManifestPath;
        if (suppliedPath is not null && string.IsNullOrWhiteSpace(suppliedPath))
        {
            throw new ArgumentException("AssemblyManifestPath must not be blank.", nameof(options));
        }
        string path;
        try
        {
            path = Path.GetFullPath(suppliedPath ?? host.GetName().Name + ".types.json", AppContext.BaseDirectory);
        }
        catch (ArgumentException error)
        {
            throw new ArgumentException("AssemblyManifestPath must be a valid path.", nameof(options), error);
        }
        var contracts = new List<Type>();
        var seen = new HashSet<Type>();
        foreach (var contract in options.PrecomputedContracts)
        {
            ValidateContract(contract, nameof(options));
            if (seen.Add(contract))
            {
                contracts.Add(contract);
            }
        }
        return new PreparationInputs(host, path, contracts.ToArray());
    }

    internal static void ValidateContract(Type contractType, string parameterName = "contractType")
    {
        ArgumentNullException.ThrowIfNull(contractType, parameterName);
        if (contractType.GetType() != typeof(object).GetType() ||
            (!contractType.IsClass && !contractType.IsInterface) || contractType.ContainsGenericParameters ||
            contractType.IsArray || contractType.IsPointer || contractType.IsByRef || contractType.IsFunctionPointer ||
            !IsDefaultRuntimeType(contractType))
        {
            throw new ArgumentException("Expected a closed runtime class or interface from the default loading context.", parameterName);
        }
    }

    private static bool IsDefaultRuntimeType(Type type)
    {
        if (type.GetType() != typeof(object).GetType() || type.Assembly.IsDynamic ||
            AssemblyLoadContext.GetLoadContext(type.Assembly) != AssemblyLoadContext.Default)
        {
            return false;
        }
        if (type.HasElementType && !IsDefaultRuntimeType(type.GetElementType()!))
        {
            return false;
        }
        foreach (var argument in type.GenericTypeArguments)
        {
            if (!IsDefaultRuntimeType(argument))
            {
                return false;
            }
        }
        return true;
    }
}

using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;
using System.Runtime.Loader;

namespace CIS.TypeManagement;

internal static class SelectedAssemblyLoader
{
    internal static IReadOnlyList<Assembly> Load(AssemblyInventory inventory, CancellationToken cancellationToken)
    {
        // Reject cheaply detectable defects across the complete selection before any new load.
        // Loading into Default is permanent and can invoke runtime-controlled callbacks.
        foreach (var selected in inventory.Assemblies)
        {
            cancellationToken.ThrowIfCancellationRequested();
            try
            {
                ValidateExecutable(selected.Path);
                ValidateIdentity(inventory, selected, AssemblyName.GetAssemblyName(selected.Path).FullName);
                var existing = FindLoaded(selected);
                if (existing is not null) { ValidateIdentity(inventory, selected, existing.FullName); }
            }
            catch (Exception error) when (error is IOException or BadImageFormatException or UnauthorizedAccessException)
            {
                throw LoadingFailure(inventory, selected, error);
            }
        }
        var assemblies = new List<Assembly>();
        foreach (var selected in inventory.Assemblies)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Assembly loaded;
            try
            {
                loaded = FindLoaded(selected)!;
                if (loaded is null)
                {
                    try
                    {
                        loaded = AssemblyLoadContext.Default.LoadFromAssemblyName(new AssemblyName(selected.Identity));
                    }
                    catch (FileNotFoundException)
                    {
                        loaded = AssemblyLoadContext.Default.LoadFromAssemblyPath(selected.Path);
                    }
                }
                if (loaded.IsDynamic || AssemblyLoadContext.GetLoadContext(loaded) != AssemblyLoadContext.Default)
                {
                    throw new BadImageFormatException("A selected runtime asset must bind to a nondynamic assembly in the default loading context.", selected.Path);
                }
                ValidateIdentity(inventory, selected, loaded.FullName);
            }
            catch (Exception error) when (error is IOException or BadImageFormatException or UnauthorizedAccessException)
            {
                throw LoadingFailure(inventory, selected, error);
            }
            assemblies.Add(loaded);
        }
        return Array.AsReadOnly(assemblies.OrderBy(assembly => assembly.FullName, StringComparer.Ordinal).ToArray());
    }

    private static Assembly? FindLoaded(SelectedAssembly selected) => AssemblyLoadContext.Default.Assemblies.FirstOrDefault(assembly =>
        !assembly.IsDynamic && string.Equals(assembly.GetName().Name, selected.SimpleName, StringComparison.OrdinalIgnoreCase));

    private static TypeManagerInitializationException LoadingFailure(AssemblyInventory inventory, SelectedAssembly selected, Exception error)
    {
        if (error is FileLoadException && FindRuntimeBindingConflict(selected) is string actualIdentity)
        {
            return new TypeManagerInitializationException(TypeManagerFailureKind.AssemblyIdentityConflict,
                "The runtime's bound assembly identity conflicts with the selected inventory.", error,
                manifestPath: inventory.ManifestPath, assetPath: selected.Path,
                assemblyIdentity: selected.Identity, actualAssemblyIdentity: actualIdentity);
        }
        return new TypeManagerInitializationException(TypeManagerFailureKind.AssemblyLoadFailure,
            "A selected assembly could not be loaded.", error, manifestPath: inventory.ManifestPath,
            assetPath: selected.Path, assemblyIdentity: selected.Identity);
    }

    private static string? FindRuntimeBindingConflict(SelectedAssembly selected)
    {
        foreach (var assembly in AssemblyLoadContext.Default.Assemblies)
        {
            if (!assembly.IsDynamic && string.Equals(assembly.GetName().Name, selected.SimpleName, StringComparison.OrdinalIgnoreCase) &&
                !string.Equals(assembly.FullName, selected.Identity, StringComparison.Ordinal))
            {
                return assembly.FullName;
            }
        }
        // Read the runtime's existing binding facts only to diagnose a failed bind.
        // This never chooses assets, parses deps/RID rules, loads an assembly, or extends the catalog.
        if (AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string platformAssemblies)
        {
            foreach (string path in platformAssemblies.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries))
            {
                try
                {
                    var identity = AssemblyName.GetAssemblyName(path);
                    if (string.Equals(identity.Name, selected.SimpleName, StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(identity.FullName, selected.Identity, StringComparison.Ordinal))
                    {
                        return identity.FullName;
                    }
                }
                catch (Exception error) when (error is IOException or BadImageFormatException or UnauthorizedAccessException)
                {
                    // A diagnostic lookup must not replace the original selected-asset failure.
                }
            }
        }
        return null;
    }

    private static void ValidateExecutable(string path)
    {
        using var stream = File.OpenRead(path);
        using var executable = new PEReader(stream);
        if (!executable.HasMetadata)
        {
            throw new BadImageFormatException("Selected file has no managed assembly metadata.", path);
        }
        var metadata = executable.GetMetadataReader();
        if (!metadata.IsAssembly)
        {
            throw new BadImageFormatException("Selected file is not an assembly.", path);
        }
        foreach (var handle in metadata.GetAssemblyDefinition().GetCustomAttributes())
        {
            var constructor = metadata.GetCustomAttribute(handle).Constructor;
            StringHandle typeNamespace;
            StringHandle typeName;
            if (constructor.Kind == HandleKind.MemberReference)
            {
                var parent = metadata.GetMemberReference((MemberReferenceHandle)constructor).Parent;
                if (parent.Kind != HandleKind.TypeReference) { continue; }
                var type = metadata.GetTypeReference((TypeReferenceHandle)parent);
                typeNamespace = type.Namespace;
                typeName = type.Name;
            }
            else if (constructor.Kind == HandleKind.MethodDefinition)
            {
                var type = metadata.GetTypeDefinition(metadata.GetMethodDefinition((MethodDefinitionHandle)constructor).GetDeclaringType());
                typeNamespace = type.Namespace;
                typeName = type.Name;
            }
            else { continue; }
            if (metadata.StringComparer.Equals(typeNamespace, "System.Runtime.CompilerServices") &&
                metadata.StringComparer.Equals(typeName, "ReferenceAssemblyAttribute"))
            {
                throw new BadImageFormatException("Selected file is a reference assembly, not an executable runtime asset.", path);
            }
        }
    }

    private static void ValidateIdentity(AssemblyInventory inventory, SelectedAssembly selected, string? actual)
    {
        if (!string.Equals(selected.Identity, actual, StringComparison.Ordinal))
        {
            throw new TypeManagerInitializationException(TypeManagerFailureKind.AssemblyIdentityConflict,
                "A selected assembly identity conflicts with its deployed or loaded identity.",
                new FileLoadException("Expected " + selected.Identity + "; observed " + actual, selected.Path),
                manifestPath: inventory.ManifestPath, assetPath: selected.Path,
                assemblyIdentity: selected.Identity, actualAssemblyIdentity: actual);
        }
    }
}

using System.Diagnostics;
using System.Diagnostics.CodeAnalysis;
using System.Reflection;
using System.Runtime.Loader;

namespace CIS.TypeManagement;

/// <summary>Prepares and owns a fixed catalog of the host's selected runtime assemblies and types.</summary>
public sealed class TypeManager : ITypeManager
{
    private readonly Dictionary<Assembly, IReadOnlyList<Type>> definedTypes;
    private readonly Dictionary<string, Type> exactNames;
    private readonly Dictionary<Type, IReadOnlyList<Type>> implementations = new();
    private readonly object queryLock = new();

    private TypeManager(IReadOnlyList<Assembly> assemblies, IReadOnlyList<Type> types,
        Dictionary<Assembly, IReadOnlyList<Type>> definedTypes, Dictionary<string, Type> exactNames)
    {
        Assemblies = assemblies;
        Types = types;
        this.definedTypes = definedTypes;
        this.exactNames = exactNames;
        PreparationReport = null!; // Assigned before the instance can leave CreateCoreAsync.
    }

    /// <inheritdoc />
    public IReadOnlyList<Assembly> Assemblies { get; }
    /// <inheritdoc />
    public IReadOnlyList<Type> Types { get; }
    /// <inheritdoc />
    public TypeManagerPreparationReport PreparationReport { get; private set; }

    /// <summary>Captures inputs and asynchronously prepares a complete catalog before returning it.</summary>
    /// <remarks>Use in an untrimmed, framework-dependent .NET 10 host before building its service container.</remarks>
    /// <exception cref="ArgumentException">An option or precomputed contract is invalid.</exception>
    /// <exception cref="ArgumentNullException">Options, the host, contracts list, or a contract element is null.</exception>
    /// <exception cref="OperationCanceledException">Cancellation is observed before publication.</exception>
    /// <exception cref="TypeManagerInitializationException">The selected deployment cannot be prepared completely.</exception>
    [RequiresUnreferencedCode("Type Manager enumerates all selected assembly definitions and requires an untrimmed deployment.")]
    public static Task<ITypeManager> CreateAsync(TypeManagerOptions options, CancellationToken cancellationToken = default)
    {
        long started = Stopwatch.GetTimestamp();
        var inputs = PreparationInputs.Capture(options);
        return CreateCoreAsync(inputs, started, cancellationToken);
    }

    private static async Task<ITypeManager> CreateCoreAsync(PreparationInputs inputs, long started,
        CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (string.IsNullOrEmpty(inputs.HostAssembly.Location))
        {
            throw new TypeManagerInitializationException(TypeManagerFailureKind.UnsupportedDeployment,
                "Type Manager requires a conventional, untrimmed, framework-dependent deployment.",
                new NotSupportedException("The host assembly has no conventional file location."),
                manifestPath: inputs.ManifestPath, assemblyIdentity: inputs.HostAssembly.FullName);
        }
        var inventory = await AssemblyInventory.ReadAsync(inputs.ManifestPath, inputs.HostAssembly, cancellationToken).ConfigureAwait(false);
        var initiallyLoaded = new HashSet<string>(AssemblyLoadContext.Default.Assemblies
            .Where(assembly => !assembly.IsDynamic).Select(assembly => assembly.FullName).OfType<string>(), StringComparer.Ordinal);
        var assemblies = SelectedAssemblyLoader.Load(inventory, cancellationToken);
        var allTypes = new List<Type>();
        var definedTypes = new Dictionary<Assembly, IReadOnlyList<Type>>();
        var names = new Dictionary<string, Type>(StringComparer.Ordinal);
        foreach (var assembly in assemblies)
        {
            cancellationToken.ThrowIfCancellationRequested();
            try
            {
                var types = assembly.GetTypes();
                foreach (var type in types)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    // Force relationship metadata while failures still prevent publication.
                    _ = type.BaseType;
                    _ = type.GetInterfaces();
                    string? name = type.AssemblyQualifiedName;
                    if (!string.IsNullOrWhiteSpace(name) && !names.TryAdd(name, type) && names[name] != type)
                    {
                        throw new TypeLoadException("Distinct definitions have the same textual identity: " + name);
                    }
                }
                Array.Sort(types, CompareTypes);
                definedTypes.Add(assembly, Array.AsReadOnly(types));
                allTypes.AddRange(types);
            }
            catch (Exception error) when (IsMetadataFailure(error))
            {
                throw DiscoveryFailure(inputs.ManifestPath, assembly, error);
            }
        }
        allTypes.Sort(CompareTypes);
        var manager = new TypeManager(assemblies, Array.AsReadOnly(allTypes.ToArray()), definedTypes, names);
        foreach (var contract in inputs.Contracts)
        {
            cancellationToken.ThrowIfCancellationRequested();
            manager.GetOrComputeImplementations(contract, inputs.ManifestPath);
        }
        var identities = assemblies.Select(assembly => assembly.FullName!).ToArray();
        manager.PreparationReport = new TypeManagerPreparationReport(Stopwatch.GetElapsedTime(started),
            allTypes.Count, inputs.Contracts.Length, identities,
            identities.Where(identity => !initiallyLoaded.Contains(identity)),
            identities.Where(initiallyLoaded.Contains));
        cancellationToken.ThrowIfCancellationRequested();
        return manager;
    }

    /// <inheritdoc />
    public IReadOnlyList<Type> GetDefinedTypes(Assembly assembly)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        if (!definedTypes.TryGetValue(assembly, out var types))
        {
            throw new ArgumentException("The assembly is outside this catalog.", nameof(assembly));
        }
        return types;
    }

    /// <inheritdoc />
    public IReadOnlyList<Type> GetImplementations(Type contractType)
    {
        PreparationInputs.ValidateContract(contractType);
        return GetOrComputeImplementations(contractType, preparationManifest: null);
    }

    private IReadOnlyList<Type> GetOrComputeImplementations(Type contractType, string? preparationManifest)
    {
        lock (queryLock)
        {
            if (implementations.TryGetValue(contractType, out var result))
            {
                return result;
            }
            var matches = new List<Type>();
            foreach (var candidate in Types)
            {
                try
                {
                    if (candidate.IsClass && !candidate.IsAbstract && !candidate.ContainsGenericParameters &&
                        contractType.IsAssignableFrom(candidate))
                    {
                        matches.Add(candidate);
                    }
                }
                catch (Exception error) when (preparationManifest is not null && IsMetadataFailure(error))
                {
                    throw DiscoveryFailure(preparationManifest, candidate.Assembly, error);
                }
            }
            result = Array.AsReadOnly(matches.ToArray());
            // CLR metadata resolution may reenter through a host callback on this thread.
            // Keep a result already published by that reentrant query.
            implementations.TryAdd(contractType, result);
            return implementations[contractType];
        }
    }

    /// <inheritdoc />
    public bool TryGetType(string assemblyQualifiedTypeName, [NotNullWhen(true)] out Type? type)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(assemblyQualifiedTypeName);
        return exactNames.TryGetValue(assemblyQualifiedTypeName, out type);
    }

    private static int CompareTypes(Type? left, Type? right)
    {
        int comparison = StringComparer.Ordinal.Compare(left!.AssemblyQualifiedName, right!.AssemblyQualifiedName);
        if (comparison != 0) { return comparison; }
        comparison = StringComparer.Ordinal.Compare(left.Assembly.FullName, right.Assembly.FullName);
        if (comparison != 0) { return comparison; }
        comparison = StringComparer.Ordinal.Compare(left.FullName ?? left.Name, right.FullName ?? right.Name);
        return comparison != 0 ? comparison : left.MetadataToken.CompareTo(right.MetadataToken);
    }

    private static bool IsMetadataFailure(Exception error)
    {
        return error is ReflectionTypeLoadException or TypeLoadException or IOException or BadImageFormatException or NotSupportedException;
    }

    private static TypeManagerInitializationException DiscoveryFailure(string manifestPath, Assembly assembly, Exception error)
    {
        return new TypeManagerInitializationException(TypeManagerFailureKind.TypeDiscoveryFailure,
            "Selected type metadata could not be discovered completely.", error,
            manifestPath: manifestPath, assetPath: assembly.Location, assemblyIdentity: assembly.FullName,
            loaderExceptions: (error as ReflectionTypeLoadException)?.LoaderExceptions.OfType<Exception>());
    }
}

namespace CIS.TypeManagement;

/// <summary>Stable categories of operational Type Manager preparation failures.</summary>
public enum TypeManagerFailureKind
{
    /// <summary>The required deployment inventory is missing, malformed or inconsistent.</summary>
    InvalidInventory = 1,
    /// <summary>A selected managed assembly could not be loaded.</summary>
    AssemblyLoadFailure = 2,
    /// <summary>The selected assembly identity conflicts with the actual runtime identity.</summary>
    AssemblyIdentityConflict = 3,
    /// <summary>Complete type or relationship discovery could not be performed.</summary>
    TypeDiscoveryFailure = 4,
    /// <summary>The deployment uses an unsupported runtime or loading model.</summary>
    UnsupportedDeployment = 5
}

namespace CIS.TypeManagement;

/// <summary>Operational failure that prevented publication of a complete Type Manager.</summary>
public sealed class TypeManagerInitializationException : Exception
{
    internal TypeManagerInitializationException(TypeManagerFailureKind kind, string message, Exception innerException,
        string? manifestPath = null, string? assetPath = null, string? assemblyIdentity = null,
        string? actualAssemblyIdentity = null, IEnumerable<Exception>? loaderExceptions = null)
        : base(Describe(message, manifestPath, assetPath, assemblyIdentity, actualAssemblyIdentity), innerException)
    {
        FailureKind = kind;
        ManifestPath = manifestPath;
        AssetPath = assetPath;
        AssemblyIdentity = assemblyIdentity;
        ActualAssemblyIdentity = actualAssemblyIdentity;
        LoaderExceptions = Array.AsReadOnly(loaderExceptions?.ToArray() ?? []);
    }

    /// <summary>Gets the stable operational failure category.</summary>
    public TypeManagerFailureKind FailureKind { get; }
    /// <summary>Gets the inventory location, if known.</summary>
    public string? ManifestPath { get; }
    /// <summary>Gets the relevant asset location, if known. Invalid paths may retain submitted text; discovery failures identify the actual loaded assembly location.</summary>
    public string? AssetPath { get; }
    /// <summary>Gets the selected full assembly identity, if known.</summary>
    public string? AssemblyIdentity { get; }
    /// <summary>Gets the conflicting observed identity, if applicable.</summary>
    public string? ActualAssemblyIdentity { get; }
    /// <summary>Gets an owned, nonmutating collection of underlying loader failures.</summary>
    public IReadOnlyList<Exception> LoaderExceptions { get; }

    private static string Describe(string message, string? manifestPath, string? assetPath,
        string? assemblyIdentity, string? actualAssemblyIdentity)
    {
        var text = new System.Text.StringBuilder(message);
        if (manifestPath is not null) { text.Append(" Manifest: '").Append(manifestPath).Append("'."); }
        if (assetPath is not null) { text.Append(" Asset: '").Append(assetPath).Append("'."); }
        if (assemblyIdentity is not null) { text.Append(" Selected identity: '").Append(assemblyIdentity).Append("'."); }
        if (actualAssemblyIdentity is not null) { text.Append(" Observed identity: '").Append(actualAssemblyIdentity).Append("'."); }
        return text.ToString();
    }
}

using System.Reflection;

namespace CIS.TypeManagement;

/// <summary>Input values captured and validated when preparation starts.</summary>
public sealed class TypeManagerOptions
{
    /// <summary>Creates options for the application's explicitly selected host assembly.</summary>
    public TypeManagerOptions(Assembly hostAssembly)
    {
        HostAssembly = hostAssembly;
    }

    /// <summary>Gets the host assembly. Preparation requires an ordinary default-context runtime assembly.</summary>
    public Assembly HostAssembly { get; }
    /// <summary>Gets an optional inventory path. Relative paths resolve from the application directory; the default is the host name plus .types.json there.</summary>
    public string? AssemblyManifestPath { get; init; }
    /// <summary>Gets closed class or interface queries to prepare before returning the manager.</summary>
    public IReadOnlyList<Type> PrecomputedContracts { get; init; } = Array.Empty<Type>();
}

namespace CIS.TypeManagement;

/// <summary>Immutable preparation facts; these are not live query-cache counters.</summary>
public sealed class TypeManagerPreparationReport
{
    internal TypeManagerPreparationReport(TimeSpan elapsed, int typeCount, int preparedContractCount,
        IEnumerable<string> selected, IEnumerable<string> loaded, IEnumerable<string> reused)
    {
        Elapsed = elapsed;
        TypeCount = typeCount;
        PreparedContractCount = preparedContractCount;
        SelectedAssemblyIdentities = Array.AsReadOnly(selected.ToArray());
        LoadedAssemblyIdentities = Array.AsReadOnly(loaded.ToArray());
        ReusedAssemblyIdentities = Array.AsReadOnly(reused.ToArray());
    }

    /// <summary>Gets preparation duration measured with a monotonic clock.</summary>
    public TimeSpan Elapsed { get; }
    /// <summary>Gets the number of selected assemblies.</summary>
    public int SelectedAssemblyCount => SelectedAssemblyIdentities.Count;
    /// <summary>Gets the number of cataloged type definitions.</summary>
    public int TypeCount { get; }
    /// <summary>Gets the number of distinct precomputed contracts.</summary>
    public int PreparedContractCount { get; }
    /// <summary>Gets selected full assembly identities in ordinal order.</summary>
    public IReadOnlyList<string> SelectedAssemblyIdentities { get; }
    /// <summary>Gets selected identities absent from the default context before the load phase.</summary>
    public IReadOnlyList<string> LoadedAssemblyIdentities { get; }
    /// <summary>Gets selected identities already present in the default context before the load phase.</summary>
    public IReadOnlyList<string> ReusedAssemblyIdentities { get; }
}

