using System.Globalization;
using System.Reflection;
using System.Text.Json;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.UnitTests;

[TestClass]
[DoNotParallelize]
public sealed class TypeManagerOrderingTests
{
    [TestMethod]
    [DataRow("en-US")]
    [DataRow("tr-TR")]
    [DataRow("sv-SE")]
    public async Task CultureAndValidInventoryOrderCannotChangePreparedOrLazyResults(string culture)
    {
        CultureInfo previous = CultureInfo.CurrentCulture;
        CultureInfo previousUi = CultureInfo.CurrentUICulture;
        string directory = Path.Combine(Path.GetTempPath(), "cis-type-manager-ordering", Guid.NewGuid().ToString("N"));
        Assembly host = typeof(TypeManagerOrderingTests).Assembly;
        Assembly core = typeof(TypeManager).Assembly;
        Assembly abstractions = typeof(Microsoft.Extensions.Logging.ILogger).Assembly;
        Assembly[] selected = [host, abstractions, core];
        string manifest = Path.Combine(directory, "host.types.json");
        try
        {
            Directory.CreateDirectory(directory);
            foreach (var assembly in selected) { File.Copy(assembly.Location, Path.Combine(directory, assembly.GetName().Name + ".dll")); }
            CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
            CultureInfo.CurrentUICulture = CultureInfo.InvariantCulture;
            WriteManifest(selected);
            var baseline = await Create(precompute: false);
            var baselineTypes = baseline.Types.ToArray();
            var baselineAssemblies = baseline.Assemblies.ToArray();
            CollectionAssert.AreEqual(new[] { core, host, abstractions }, baselineAssemblies);
            var baselineObjects = baseline.GetImplementations<object>().ToArray();

            CultureInfo.CurrentCulture = CultureInfo.GetCultureInfo(culture);
            CultureInfo.CurrentUICulture = CultureInfo.CurrentCulture;
            // These fixture names deliberately distinguish linguistic and ordinal
            // ordering. The expected query order is specified independently.
            Assert.IsLessThan(0, StringComparer.CurrentCulture.Compare(nameof(ÉclairCandidate), nameof(ZebraCandidate)));
            Assert.AreEqual('\u00C9', nameof(ÉclairCandidate)[0]);
            Type[] expected = [typeof(ZebraCandidate), typeof(ÉclairCandidate)];
            foreach (bool reverse in new[] { false, true })
            {
                WriteManifest(reverse ? selected.Reverse().ToArray() : selected);
                foreach (bool precompute in new[] { false, true })
                {
                    var manager = await Create(precompute);
                    CollectionAssert.AreEqual(baselineAssemblies, manager.Assemblies.ToArray());
                    CollectionAssert.AreEqual(baselineTypes, manager.Types.ToArray());
                    AssertOrdinalFixtureOrder(manager.Types);
                    AssertOrdinalFixtureOrder(manager.GetDefinedTypes(host));
                    CollectionAssert.AreEqual(baselineObjects, manager.GetImplementations<object>().ToArray());
                    var candidates = manager.GetImplementations<ICultureMarker>();
                    CollectionAssert.AreEqual(expected, candidates.ToArray());
                    Assert.AreSame(candidates, manager.GetImplementations(typeof(ICultureMarker)));
                    Assert.AreEqual(precompute ? 2 : 0, manager.PreparationReport.PreparedContractCount);
                    foreach (var assembly in selected)
                    {
                        CollectionAssert.AreEqual(baseline.GetDefinedTypes(assembly).ToArray(), manager.GetDefinedTypes(assembly).ToArray());
                    }
                    foreach (var type in expected)
                    {
                        Assert.IsTrue(manager.TryGetType(type.AssemblyQualifiedName!, out var found));
                        Assert.AreSame(type, found);
                    }
                    await Task.WhenAll(Enumerable.Range(0, 16).Select(_ => Task.Run(() =>
                    {
                        Assert.AreSame(candidates, manager.GetImplementations<ICultureMarker>());
                        CollectionAssert.AreEqual(baselineObjects, manager.GetImplementations<object>().ToArray());
                    })));
                }
            }
        }
        finally
        {
            CultureInfo.CurrentCulture = previous;
            CultureInfo.CurrentUICulture = previousUi;
            if (Directory.Exists(directory)) { Directory.Delete(directory, recursive: true); }
        }

        void WriteManifest(IEnumerable<Assembly> assemblies) => File.WriteAllText(manifest, JsonSerializer.Serialize(new
        {
            schemaVersion = 1,
            hostAssembly = host.FullName,
            assemblies = assemblies.Select(assembly => new
            {
                assemblyName = assembly.FullName,
                relativePath = assembly.GetName().Name + ".dll"
            }).ToArray()
        }));

        Task<ITypeManager> Create(bool precompute) => TypeManager.CreateAsync(new TypeManagerOptions(host)
        {
            AssemblyManifestPath = manifest,
            PrecomputedContracts = precompute ? [typeof(ICultureMarker), typeof(object)] : []
        });
    }

    private static void AssertOrdinalFixtureOrder(IReadOnlyList<Type> types)
    {
        var values = types.ToArray();
        int zebraIndex = Array.IndexOf(values, typeof(ZebraCandidate));
        int accentedIndex = Array.IndexOf(values, typeof(ÉclairCandidate));
        Assert.IsTrue(zebraIndex >= 0 && accentedIndex > zebraIndex,
            "Ordinal ordering must place ZebraCandidate before ÉclairCandidate.");
    }

    private interface ICultureMarker { }
    private sealed class ZebraCandidate : ICultureMarker { }
    private sealed class ÉclairCandidate : ICultureMarker { }
}

using System.Reflection;
using System.Reflection.Emit;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.ArchitectureTests;

[TestClass]
public sealed class TypeManagerRuntimeArchitectureTests
{
    private static readonly Assembly Core = typeof(TypeManager).Assembly;
    private static readonly Dictionary<short, OpCode> Codes = typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static)
        .Where(field => field.FieldType == typeof(OpCode)).Select(field => (OpCode)field.GetValue(null)!).ToDictionary(code => code.Value);

    [TestMethod]
    public void ModuleCannotActivateApplicationsSubscribeResolversOrDependOnOtherModules()
    {
        foreach (var type in Core.GetTypes().Where(type => type.Namespace == "CIS.TypeManagement"))
        {
            foreach (var method in Methods(type))
            {
                foreach (var target in Calls(method)) { RejectForbiddenCall(target, query: false); }
            }
        }
    }

    [TestMethod]
    public void PublicQueryCallGraphsCannotReadFilesLoadOrEnumerateAssemblies()
    {
        foreach (var name in new[] { nameof(TypeManager.GetDefinedTypes), nameof(TypeManager.GetImplementations), nameof(TypeManager.TryGetType) })
        {
            InspectQuery(typeof(TypeManager).GetMethod(name)!);
        }
        InspectQuery(typeof(TypeManagerExtensions).GetMethod(nameof(TypeManagerExtensions.GetImplementations))!.MakeGenericMethod(typeof(object)));
    }

    [TestMethod]
    public void OnlyThePreparationStateMachineContainsADefinitionEnumerationCall()
    {
        var callers = Core.GetTypes().Where(type => type.Namespace == "CIS.TypeManagement").SelectMany(Methods)
            .SelectMany(method => Calls(method).Where(target => target.DeclaringType == typeof(Assembly) && target.Name == nameof(Assembly.GetTypes)).Select(_ => method)).ToArray();
        Assert.HasCount(1, callers);
        Assert.AreEqual("MoveNext", callers[0].Name);
        StringAssert.Contains(callers[0].DeclaringType!.Name, "<CreateCoreAsync>");
        // This is a structural guard, not a replacement for executed enumeration counters.
    }

    [TestMethod]
    [DataRow(nameof(ActivationProbe))]
    [DataRow(nameof(EnumerationProbe))]
    [DataRow(nameof(LoadProbe))]
    [DataRow(nameof(ResolverProbe))]
    [DataRow(nameof(FileProbe))]
    [DataRow(nameof(IndirectFileProbe))]
    public void QueryInspectorRejectsRealForbiddenAndTransitiveCalls(string method)
    {
        Assert.ThrowsExactly<InvalidDataException>(() => InspectQuery(typeof(TypeManagerRuntimeArchitectureTests).GetMethod(method, BindingFlags.NonPublic | BindingFlags.Static)!));
    }

    private static object? ActivationProbe(Type type) => Activator.CreateInstance(type);
    private static Type[] EnumerationProbe(Assembly assembly) => assembly.GetTypes();
    private static Assembly LoadProbe(string name) => Assembly.Load(name);
    private static void ResolverProbe() => AppDomain.CurrentDomain.AssemblyResolve += (_, _) => null;
    private static string FileProbe(string path) => File.ReadAllText(path);
    private static string IndirectFileProbe(string path) => FileProbe(path);

    private static IEnumerable<MethodBase> Methods(Type type) => type
        .GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance | BindingFlags.DeclaredOnly)
        .Cast<MethodBase>().Concat(type.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance));

    private static void InspectQuery(MethodBase root)
    {
        var pending = new Stack<MethodBase>();
        var visited = new HashSet<MethodBase>();
        pending.Push(root);
        while (pending.TryPop(out var method))
        {
            if (!visited.Add(method)) { continue; }
            foreach (var target in Calls(method))
            {
                RejectForbiddenCall(target, query: true);
                if (target.Module.Assembly == Core || target.DeclaringType == typeof(TypeManagerRuntimeArchitectureTests)) { pending.Push(target); }
            }
        }
    }

    private static void RejectForbiddenCall(MethodBase target, bool query)
    {
        string type = target.DeclaringType?.FullName ?? "";
        bool forbidden = type == "System.Activator" || type.StartsWith("CIS.Logging", StringComparison.Ordinal) ||
            type.StartsWith("CIS.Configuration", StringComparison.Ordinal) || type == "CIS.EnvironmentOptions" ||
            type.StartsWith("Microsoft.Extensions.DependencyInjection", StringComparison.Ordinal) || type.StartsWith("Microsoft.Build", StringComparison.Ordinal) ||
            type is "System.Threading.Thread" or "System.Threading.Timer" or "System.Threading.ThreadPool" or "System.IO.Directory" ||
            type == "System.Runtime.CompilerServices.RuntimeHelpers" && target.Name == "RunClassConstructor" ||
            type.StartsWith("System.Reflection.", StringComparison.Ordinal) && !type.StartsWith("System.Reflection.Metadata.", StringComparison.Ordinal) && target.Name is "Invoke" or "GetCustomAttributes" ||
            type == "System.Attribute" && target.Name.StartsWith("GetCustomAttribute", StringComparison.Ordinal) ||
            type == "System.Threading.Tasks.Task" && target.Name == "Run" ||
            target.Name is "add_AssemblyLoad" or "add_AssemblyResolve" or "add_Resolving" or "add_ResolvingUnmanagedDll";
        if (query)
        {
            forbidden |= type.StartsWith("System.IO.", StringComparison.Ordinal) ||
                type == "System.Reflection.Assembly" && target.Name is "GetTypes" or "GetExportedTypes" or "get_DefinedTypes" or "GetType" or "Load" or "LoadFrom" or "LoadFile" ||
                type == "System.Runtime.Loader.AssemblyLoadContext" && target.Name.StartsWith("Load", StringComparison.Ordinal) ||
                type == "System.Type" && target.Name == "GetType" && target.IsStatic;
        }
        if (forbidden) { throw new InvalidDataException("Forbidden Type Manager call: " + type + "." + target.Name); }
    }

    private static IEnumerable<MethodBase> Calls(MethodBase method)
    {
        byte[]? body = method.GetMethodBody()?.GetILAsByteArray();
        if (body is null) { yield break; }
        for (int offset = 0; offset < body.Length;)
        {
            short key = body[offset++] == 0xfe ? unchecked((short)(0xfe00 | body[offset++])) : body[offset - 1];
            var code = Codes[key];
            if (code.OperandType == OperandType.InlineMethod)
            {
                yield return method.Module.ResolveMethod(BitConverter.ToInt32(body, offset), method.DeclaringType?.GetGenericArguments(),
                    method.IsGenericMethod ? method.GetGenericArguments() : null)!;
            }
            offset += code.OperandType switch
            {
                OperandType.InlineNone => 0,
                OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar => 1,
                OperandType.InlineVar => 2,
                OperandType.InlineI8 or OperandType.InlineR => 8,
                OperandType.InlineSwitch => 4 + 4 * BitConverter.ToInt32(body, offset),
                _ => 4
            };
        }
    }
}

using System.Reflection;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text.Json;
using CIS.TypeManagement;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CIS.Tests.BusinessCases;

[TestClass]
[DoNotParallelize]
public sealed class TypeManagerStartupStories
{
    private string directory = null!;
    private string manifest = null!;
    private static Assembly Host => typeof(TypeManagerStartupStories).Assembly;

    public TestContext TestContext { get; set; } = null!;

    [TestInitialize]
    public void Initialize()
    {
        directory = Path.Combine(Path.GetTempPath(), "cis-type-manager-stories", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(directory);
        // A selected file may identify an assembly already loaded from another path.
        File.Copy(Host.Location, Path.Combine(directory, "Host.dll"));
        manifest = Path.Combine(directory, "host.types.json");
        WriteInventory();
        Activation.Count = 0;
        TestContext.WriteLine(JsonSerializer.Serialize(new
        {
            runtime = RuntimeInformation.FrameworkDescription,
            os = OperatingSystem.IsWindows() ? "windows" : OperatingSystem.IsLinux() ? "linux" : "unsupported",
            architecture = RuntimeInformation.ProcessArchitecture.ToString(),
            coreSha256 = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(typeof(TypeManager).Assembly.Location)))
        }));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (Directory.Exists(directory)) { Directory.Delete(directory, recursive: true); }
    }

    [TestMethod]
    [DataRow(false)]
    [DataRow(true)]
    public async Task PreparationHandsUsableCatalogToApplicationBeforeItCreatesServices(bool precompute)
    {
        var events = new List<string>();
        var options = Options(precompute);
        var application = await StartAsync(options, manager =>
        {
            events.Add("application factory");
            Assert.AreEqual(0, Activation.Count, "Discovery must leave application construction to its owner.");
            var matches = manager.GetImplementations<ISettings>();
            CollectionAssert.AreEqual(new[] { typeof(MailSettings) }, matches.ToArray());
            Assert.AreSame(matches, manager.GetImplementations(typeof(ISettings)));
            Assert.IsTrue(manager.TryGetType(matches[0].AssemblyQualifiedName!, out var found));
            Assert.AreSame(typeof(MailSettings), found);
            var settings = MailSettings.Create("smtp.example.test");
            events.Add("application activation");
            return new Application(manager, settings);
        }, events);

        CollectionAssert.AreEqual(new[] { "preparing", "prepared", "application factory", "application activation" }, events);
        Assert.AreEqual(1, Activation.Count);
        Assert.AreEqual("smtp.example.test", application.Settings.Endpoint);
        Assert.AreEqual(precompute ? 1 : 0, application.Manager.PreparationReport.PreparedContractCount);
        Assert.AreEqual(1, application.Manager.PreparationReport.SelectedAssemblyCount);
        Assert.AreEqual(0, application.Manager.PreparationReport.LoadedAssemblyIdentities.Count);
        CollectionAssert.AreEqual(new[] { Host.FullName }, application.Manager.PreparationReport.ReusedAssemblyIdentities.ToArray());
        Assert.AreEqual(application.Manager.Types.Count, application.Manager.PreparationReport.TypeCount);
        CollectionAssert.AreEquivalent(application.Manager.Types.ToArray(), application.Manager.GetDefinedTypes(Host).ToArray());
    }

    [TestMethod]
    [DataRow("invalid inventory", TypeManagerFailureKind.InvalidInventory)]
    [DataRow("missing inventory", TypeManagerFailureKind.InvalidInventory)]
    [DataRow("missing assembly", TypeManagerFailureKind.InvalidInventory)]
    [DataRow("corrupt assembly", TypeManagerFailureKind.AssemblyLoadFailure)]
    public async Task FailedPreparationNeverInvokesApplicationFactory(string damage, TypeManagerFailureKind expectedKind)
    {
        switch (damage)
        {
            case "invalid inventory": File.WriteAllText(manifest, "{"); break;
            case "missing inventory": File.Delete(manifest); break;
            case "corrupt assembly": File.WriteAllText(Path.Combine(directory, "Host.dll"), "not a managed assembly"); break;
            case "missing assembly": File.Delete(Path.Combine(directory, "Host.dll")); break;
            default: throw new ArgumentException("Unknown deployment damage.", nameof(damage));
        }
        var events = new List<string>();
        int factoryCalls = 0;
        var error = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(() => StartAsync(Options(), _ => ++factoryCalls, events));

        Assert.AreEqual(expectedKind, error.FailureKind);
        Assert.AreEqual(manifest, error.ManifestPath);
        Assert.IsNotNull(error.InnerException);
        if (damage is "missing assembly" or "corrupt assembly")
        {
            Assert.AreEqual(Path.Combine(directory, "Host.dll"), error.AssetPath);
            Assert.AreEqual(Host.FullName, error.AssemblyIdentity);
        }
        Assert.AreEqual(0, factoryCalls);
        Assert.AreEqual(0, Activation.Count);
        CollectionAssert.AreEqual(new[] { "preparing" }, events);
    }

    [TestMethod]
    public async Task PreCanceledPreparationNeverInvokesApplicationFactory()
    {
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        var events = new List<string>();
        int factoryCalls = 0;
        var startup = StartAsync(Options(), _ => ++factoryCalls, events, cancellation.Token);
        await Assert.ThrowsAsync<OperationCanceledException>(() => startup);
        Assert.IsTrue(startup.IsCanceled);
        Assert.AreEqual(0, factoryCalls);
        Assert.AreEqual(0, Activation.Count);
        CollectionAssert.AreEqual(new[] { "preparing" }, events);
    }

    [TestMethod]
    public async Task ConcurrentConsumersReusePreparedCatalogWhileApplicationOwnsObjectLifetime()
    {
        var manager = await TypeManager.CreateAsync(Options(precompute: true));
        var prepared = manager.GetImplementations<ISettings>();
        var report = manager.PreparationReport;
        var consumers = await Task.WhenAll(Enumerable.Range(0, 16).Select(_ => Task.Run(() =>
        {
            Assert.AreSame(prepared, manager.GetImplementations<ISettings>());
            Assert.AreSame(report, manager.PreparationReport);
            return new Application(manager, MailSettings.Create("request.example.test"));
        })));
        Assert.AreEqual(16, Activation.Count);
        Assert.AreEqual(16, consumers.Select(item => item.Settings).Distinct().Count());
        foreach (var consumer in consumers) { Assert.AreSame(manager, consumer.Manager); }
        Assert.Throws<NotSupportedException>(() => ((IList<Type>)prepared)[0] = typeof(SettingsBase));
        CollectionAssert.AreEqual(new[] { typeof(MailSettings) }, manager.GetImplementations<ISettings>().ToArray());
        Assert.AreEqual(1, report.PreparedContractCount);
    }

    [TestMethod]
    public async Task RunningApplicationKeepsSnapshotWhileNextStartupValidatesChangedInventory()
    {
        var manager = await TypeManager.CreateAsync(Options());
        var types = manager.Types;
        var report = manager.PreparationReport;
        File.WriteAllText(manifest, "{");
        File.Delete(Path.Combine(directory, "Host.dll"));

        // The first query is deliberately after the deployment files change.
        CollectionAssert.AreEqual(new[] { typeof(MailSettings) }, manager.GetImplementations<ISettings>().ToArray());
        Assert.AreSame(types, manager.Types);
        Assert.AreSame(report, manager.PreparationReport);
        Assert.IsTrue(manager.TryGetType(typeof(MailSettings).AssemblyQualifiedName!, out var found));
        Assert.AreSame(typeof(MailSettings), found);
        var error = await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(() => TypeManager.CreateAsync(Options()));
        Assert.AreEqual(TypeManagerFailureKind.InvalidInventory, error.FailureKind);
        Assert.AreEqual(0, Activation.Count);
    }

    [TestMethod]
    public async Task FailedStartupCanBeRepairedWithIndependentPreparation()
    {
        File.WriteAllText(manifest, "{");
        var failed = TypeManager.CreateAsync(Options());
        await Assert.ThrowsExactlyAsync<TypeManagerInitializationException>(() => failed);
        WriteInventory();
        var events = new List<string>();
        var repaired = await StartAsync(Options(), manager => new Application(manager, MailSettings.Create("repaired.example.test")), events);

        Assert.IsTrue(failed.IsFaulted, "A new preparation must not mutate the original failed task.");
        CollectionAssert.AreEqual(new[] { "preparing", "prepared" }, events);
        Assert.AreEqual("repaired.example.test", repaired.Settings.Endpoint);
        Assert.AreEqual(1, Activation.Count);
        CollectionAssert.AreEqual(new[] { typeof(MailSettings) }, repaired.Manager.GetImplementations<ISettings>().ToArray());
        using var exclusive = new FileStream(manifest, FileMode.Open, FileAccess.ReadWrite, FileShare.None);
        Assert.IsTrue(exclusive.CanWrite);
    }

    // This is the application's ordering policy, not an extra Type Manager API.
    private static async Task<T> StartAsync<T>(TypeManagerOptions options, Func<ITypeManager, T> factory,
        List<string> events, CancellationToken cancellationToken = default)
    {
        events.Add("preparing");
        var manager = await TypeManager.CreateAsync(options, cancellationToken);
        events.Add("prepared");
        return factory(manager);
    }

    private TypeManagerOptions Options(bool precompute = false) => new(Host)
    {
        AssemblyManifestPath = manifest,
        PrecomputedContracts = precompute ? [typeof(ISettings)] : []
    };

    private void WriteInventory() => File.WriteAllText(manifest, JsonSerializer.Serialize(new
    {
        schemaVersion = 1,
        hostAssembly = Host.FullName,
        assemblies = new[] { new { assemblyName = Host.FullName, relativePath = "Host.dll" } }
    }));

    private sealed record Application(ITypeManager Manager, MailSettings Settings);
    private interface ISettings;
    private abstract class SettingsBase : ISettings;
    private sealed class OpenSettings<T> : SettingsBase;
    private readonly record struct ValueSettings : ISettings;
    private sealed class MailSettings : SettingsBase
    {
        private MailSettings(string endpoint)
        {
            Endpoint = endpoint;
            Interlocked.Increment(ref Activation.Count);
        }
        public string Endpoint { get; }
        internal static MailSettings Create(string endpoint) => new(endpoint);
    }
    private static class Activation
    {
        internal static int Count;
    }
}
